#!/usr/bin/env bash
# bootstrap-secrets.sh <env> — create a BylineCRM environment's state directory and env files (P5-4a, P5-4c).
#
# Runs ON the VPS, as root, once (and again safely at any time — every release runs it): it never
# overwrites a secret that already exists and never prints one.
#
# Touches only:
#   $BYLINECRM_RUNTIME (lib.sh): the directory, data/{postgres,valkey,attachments}, web-dynamic/,
#   postgres.env (0600), <env>.env (0600) and — once a remote was given — backup.env (0600, #166).
# Nothing of NewswireOS.
#
# Secrets are generated on the box with openssl and stay there: the Postgres owner password, the
# restricted app-role password (both hex, so they need no escaping inside a URL) and SECRETS_KEY
# (32 random bytes, base64 — what the API's env schema requires). Every other value is derived or
# fixed and is rewritten on each run, so changing this script and re-running it updates them.
#
# The variables mirror apps/api/src/config/env.ts; the API refuses to boot on a missing one.

set -euo pipefail

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# What the caller said about the offsite backup, before lib.sh fills the defaults in (#166).
GIVEN_BACKUP_REMOTE=${BYLINECRM_BACKUP_REMOTE-}
GIVEN_RCLONE_CONF=${BYLINECRM_RCLONE_CONF-}
# shellcheck source=lib.sh
. "$HERE/lib.sh"
bylinecrm_env "${1:?usage: bootstrap-secrets.sh <staging|production>}"

RUNTIME=$BYLINECRM_RUNTIME
PUBLIC_URL=$BYLINECRM_PUBLIC_URL
# The api image runs as the `node` user (uid 1000, gid 1000); it writes attachments.
API_UID=${BYLINECRM_API_UID:-1000}
API_GID=${BYLINECRM_API_GID:-1000}

APP_ENV=$BYLINECRM_APP_ENV
PG_ENV=$BYLINECRM_PG_ENV

umask 077
mkdir -p "$RUNTIME/data/postgres" "$RUNTIME/data/valkey" "$RUNTIME/data/attachments" "$RUNTIME/web-dynamic"
chmod 700 "$RUNTIME"
chown "$API_UID:$API_GID" "$RUNTIME/data/attachments"
# The web containers read this directory (nginx runs unprivileged inside them).
chmod 755 "$RUNTIME/web-dynamic"

# Reads KEY's value from FILE, or nothing when the file or the key is absent.
existing() {
    local file=$1 key=$2
    [ -f "$file" ] || return 0
    sed -n "s/^${key}=//p" "$file" | head -n 1
}

# The stored value, or a freshly generated one when there is none yet.
keep_or_generate() {
    local file=$1 key=$2 generator=$3 value
    value=$(existing "$file" "$key")
    if [ -z "$value" ]; then
        value=$($generator)
        echo "bootstrap-secrets: generated ${key}" >&2
    else
        echo "bootstrap-secrets: kept existing ${key}" >&2
    fi
    printf '%s' "$value"
}

hex24() { openssl rand -hex 24; }
key32() { openssl rand -base64 32 | tr -d '\n'; }

PG_PASSWORD=$(keep_or_generate "$PG_ENV" POSTGRES_PASSWORD hex24)
APP_DB_PASSWORD=$(keep_or_generate "$APP_ENV" APP_DB_PASSWORD hex24)
SECRETS_KEY=$(keep_or_generate "$APP_ENV" SECRETS_KEY key32)

# Operator-installed secret: the Resend API key transactional mail is sent with (#93). It is never
# generated or passed here — install-resend-key.sh writes it from stdin — so a re-run keeps whatever
# is stored, and writes no line at all until one is installed (an empty value would stop the api).
RESEND_API_KEY=$(existing "$APP_ENV" RESEND_API_KEY)
if [ -n "$RESEND_API_KEY" ]; then
    echo "bootstrap-secrets: kept existing RESEND_API_KEY" >&2
else
    echo "bootstrap-secrets: no RESEND_API_KEY yet — install it with install-resend-key.sh $BYLINECRM_ENV" >&2
fi

# Operator-set (not secret, not derived): the platform admins (P0-14). Pass
# BYLINECRM_PLATFORM_ADMIN_EMAILS to change the list; otherwise the stored list is kept, so a re-run
# never drops it. Empty is valid and means nobody can create a workspace.
if [ -n "${BYLINECRM_PLATFORM_ADMIN_EMAILS+set}" ]; then
    PLATFORM_ADMIN_EMAILS=$BYLINECRM_PLATFORM_ADMIN_EMAILS
    echo "bootstrap-secrets: set PLATFORM_ADMIN_EMAILS from BYLINECRM_PLATFORM_ADMIN_EMAILS" >&2
else
    PLATFORM_ADMIN_EMAILS=$(existing "$APP_ENV" PLATFORM_ADMIN_EMAILS)
    echo "bootstrap-secrets: kept existing PLATFORM_ADMIN_EMAILS" >&2
fi

write_atomically() {
    local target=$1 tmp
    tmp=$(mktemp "${target}.XXXXXX")
    cat >"$tmp"
    chmod 600 "$tmp"
    mv -f "$tmp" "$target"
}

write_atomically "$PG_ENV" <<EOF
# Generated by deploy/env/bootstrap-secrets.sh ${BYLINECRM_ENV} — the Postgres container only.
POSTGRES_USER=bylinecrm
POSTGRES_DB=bylinecrm
POSTGRES_PASSWORD=${PG_PASSWORD}
EOF

write_atomically "$APP_ENV" <<EOF
# Generated by deploy/env/bootstrap-secrets.sh ${BYLINECRM_ENV} — the api and migrate containers.
# Re-run the script to change a derived value; secrets are kept. Mirrors apps/api/src/config/env.ts.
NODE_ENV=production
APP_DB_PASSWORD=${APP_DB_PASSWORD}
DATABASE_URL=postgresql://bylinecrm:${PG_PASSWORD}@postgres:5432/bylinecrm
RLS_DATABASE_URL=postgresql://bylinecrm_app:${APP_DB_PASSWORD}@postgres:5432/bylinecrm
REDIS_URL=redis://valkey:6379
PORT=3000
APP_URL=${PUBLIC_URL}
WEB_URL=${PUBLIC_URL}
FILE_STORAGE_ROOT=/data/attachments
SECRETS_KEY=${SECRETS_KEY}
WEBHOOK_WORKER=1
WEBHOOK_ALLOW_PRIVATE_TARGETS=0
MAIL_SYNC_WORKER=1
MAIL_SEND_WORKER=1
OUTBOX_RELAY=1
DB_QUERY_EVENTS=0
# The URL is public: sign-up stays closed; platform admins create workspaces (P0-14). Never open.
SIGNUP_MODE=closed
PLATFORM_ADMIN_EMAILS=${PLATFORM_ADMIN_EMAILS}
# Transactional mail (#93, D-249): Resend, from Pinion Newswire's verified domain.
MAIL_FROM=BylineCRM <no-reply@pinionnewswire.com>
${RESEND_API_KEY:+RESEND_API_KEY=${RESEND_API_KEY}}
EOF

# Operator-set (#166): the offsite backup remote and the rclone config it is in, read by lib.sh for the
# backup unit and a manual run alike. Pass BYLINECRM_BACKUP_REMOTE / BYLINECRM_RCLONE_CONF to set or
# change one; otherwise what is stored is kept, so a re-run never drops it. Nothing is written until
# one was given: with no file the defaults in lib.sh apply.
BACKUP_ENV="$RUNTIME/backup.env"
BACKUP_REMOTE=$GIVEN_BACKUP_REMOTE
RCLONE_CONF=$GIVEN_RCLONE_CONF
if [ -n "$BACKUP_REMOTE" ]; then
    echo "bootstrap-secrets: set BYLINECRM_BACKUP_REMOTE from the environment" >&2
else
    BACKUP_REMOTE=$(existing "$BACKUP_ENV" BYLINECRM_BACKUP_REMOTE)
    if [ -n "$BACKUP_REMOTE" ]; then echo "bootstrap-secrets: kept existing BYLINECRM_BACKUP_REMOTE" >&2; fi
fi
if [ -n "$RCLONE_CONF" ]; then
    echo "bootstrap-secrets: set BYLINECRM_RCLONE_CONF from the environment" >&2
else
    RCLONE_CONF=$(existing "$BACKUP_ENV" BYLINECRM_RCLONE_CONF)
    if [ -n "$RCLONE_CONF" ]; then echo "bootstrap-secrets: kept existing BYLINECRM_RCLONE_CONF" >&2; fi
fi
if [ -n "$BACKUP_REMOTE" ] || [ -n "$RCLONE_CONF" ]; then
    {
        echo "# Generated by deploy/env/bootstrap-secrets.sh ${BYLINECRM_ENV} — the offsite backup (#166), read by lib.sh."
        echo "# Re-run with BYLINECRM_BACKUP_REMOTE / BYLINECRM_RCLONE_CONF to change a value; otherwise it is kept."
        if [ -n "$BACKUP_REMOTE" ]; then echo "BYLINECRM_BACKUP_REMOTE=${BACKUP_REMOTE}"; fi
        if [ -n "$RCLONE_CONF" ]; then echo "BYLINECRM_RCLONE_CONF=${RCLONE_CONF}"; fi
    } | write_atomically "$BACKUP_ENV"
    echo "bootstrap-secrets: wrote ${BACKUP_ENV} (0600)" >&2
else
    echo "bootstrap-secrets: no backup.env — the offsite remote is lib.sh's default until BYLINECRM_BACKUP_REMOTE is given" >&2
fi

echo "bootstrap-secrets: wrote ${PG_ENV} and ${APP_ENV} (0600); no secret was printed" >&2
